{
  "name": "持久化存储系统",
  "name_en": "Persistent Storage System",
  "manufacturer": "",
  "description": "这是一个用于科研数据管理软件的持久化存储组件，而非独立物理仪器。它用于将实验项目、数据项属性、项目关系以及外部数据保存到文件或内存中，支持加载、迁移、恢复、事务处理和存储清理等操作。",
  "description_en": "This is a persistent storage component for scientific data management software rather than a standalone physical instrument. It is used to store experiment projects, data item properties, item relationships, and external data in files or memory, with support for loading, migration, restoration, transactions, and storage cleanup.",
  "tag_hints": [
    "data persistence",
    "scientific data management",
    "project storage",
    "metadata storage",
    "file storage",
    "data migration",
    "transactional writes"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭存储系统",
      "description_en": "Close the storage system"
    },
    {
      "action_name": "auto-reset",
      "description": "重置存储系统",
      "description_en": "Reset the storage system"
    },
    {
      "action_name": "auto-set_root_item",
      "description": "设置根项目",
      "description_en": "Set the root item"
    },
    {
      "action_name": "auto-unload_item",
      "description": "卸载项目",
      "description_en": "Unload an item"
    },
    {
      "action_name": "auto-load_properties",
      "description": "加载存储属性",
      "description_en": "Load stored properties"
    },
    {
      "action_name": "auto-read_project_properties",
      "description": "读取项目属性",
      "description_en": "Read project properties"
    },
    {
      "action_name": "auto-migrate_to_latest",
      "description": "迁移到最新存储格式",
      "description_en": "Migrate to the latest storage format"
    },
    {
      "action_name": "auto-insert_relationship_item",
      "description": "在关系中插入项目",
      "description_en": "Insert an item into a relationship"
    },
    {
      "action_name": "auto-remove_relationship_item",
      "description": "从关系中移除项目",
      "description_en": "Remove an item from a relationship"
    },
    {
      "action_name": "auto-load_relationship_item",
      "description": "加载关系项目",
      "description_en": "Load a relationship item"
    },
    {
      "action_name": "auto-unload_relationship_item",
      "description": "卸载关系项目",
      "description_en": "Unload a relationship item"
    },
    {
      "action_name": "auto-load_component_item",
      "description": "加载组件项目",
      "description_en": "Load a component item"
    },
    {
      "action_name": "auto-set_component_item",
      "description": "设置组件项目",
      "description_en": "Set a component item"
    },
    {
      "action_name": "auto-set_property",
      "description": "设置对象属性",
      "description_en": "Set an object property"
    },
    {
      "action_name": "auto-clear_property",
      "description": "清除对象属性",
      "description_en": "Clear an object property"
    },
    {
      "action_name": "auto-read_external_data",
      "description": "读取外部数据",
      "description_en": "Read external data"
    },
    {
      "action_name": "auto-write_external_data",
      "description": "写入外部数据",
      "description_en": "Write external data"
    },
    {
      "action_name": "auto-reserve_external_data",
      "description": "预留外部数据存储空间",
      "description_en": "Reserve storage space for external data"
    },
    {
      "action_name": "auto-enter_write_delay",
      "description": "进入延迟写入状态",
      "description_en": "Enter delayed-write mode"
    },
    {
      "action_name": "auto-exit_write_delay",
      "description": "退出延迟写入状态",
      "description_en": "Exit delayed-write mode"
    },
    {
      "action_name": "auto-is_write_delayed",
      "description": "检查是否处于延迟写入状态",
      "description_en": "Check whether delayed-write mode is active"
    },
    {
      "action_name": "auto-rewrite_item",
      "description": "重写项目存储内容",
      "description_en": "Rewrite an item's stored content"
    },
    {
      "action_name": "auto-restore_item",
      "description": "恢复项目",
      "description_en": "Restore an item"
    },
    {
      "action_name": "auto-prune",
      "description": "清理未使用存储数据",
      "description_en": "Prune unused stored data"
    },
    {
      "action_name": "auto-enter_transaction",
      "description": "开始存储事务",
      "description_en": "Enter a storage transaction"
    },
    {
      "action_name": "auto-exit_transaction",
      "description": "结束存储事务",
      "description_en": "Exit a storage transaction"
    }
  ]
}

